/* Generated by tools/build_lines.py from picks/g15.txt. Every line is from: NCERT XII (old) Unit 7. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("g15", "NCERT XII (old) Unit 7", [{"sec": "Occurrence","ids": [9],"t": "Group 15: N, P, As, Sb, Bi, Mc.","exc": false,"tab": false,"src": "p15","page": 1,"o": "Group 15 includes nitrogen, phosphorus, arsenic, antimony, bismuth and moscovium."},{"sec": "Occurrence","ids": [10],"t": "Down the group: non-metal → metalloid → metal.","exc": false,"tab": false,"src": "p15","page": 1,"o": "As we go down the group, there is a shift from nonmetallic to metallic through metalloidic character."},{"sec": "Occurrence","ids": [11],"t": "N, P non-metals; As, Sb metalloids; Bi, Mc metals.","exc": false,"tab": false,"src": "p15","page": 1,"o": "Nitrogen and phosphorus are non-metals, arsenic and antimony metalloids, bismuth and moscovium are typical metals."},{"sec": "Occurrence","ids": [12],"t": "N2 is 78% of the atmosphere by volume.","exc": false,"tab": false,"src": "p15","page": 1,"o": "Molecular nitrogen comprises 78% by volume of the atmosphere."},{"sec": "Occurrence","ids": [13],"t": "Crust: NaNO3 (Chile saltpetre), KNO3 (Indian saltpetre).","exc": false,"tab": false,"src": "p15","page": 1,"o": "In the earth's crust, it occurs as sodium nitrate, NaNO3 (called Chile saltpetre) and potassium nitrate (Indian saltpetre)."},{"sec": "Occurrence","ids": [16,17,18],"t": "P: apatite family Ca9(PO4)6·CaX2 (X = F, Cl, OH), e.g. fluorapatite Ca9(PO4)6·CaF2 (phosphate rock).","exc": false,"tab": false,"src": "p15","page": 2,"o": "Phosphorus occurs in minerals of the apatite family, Ca9(PO4)6.CaX2 (X = F, Cl or OH) (e.g., fluorapatite Ca9(PO4)6.CaF2) which are the main components of phosphate rocks."},{"sec": "Occurrence","ids": [22],"t": "As, Sb, Bi occur mainly as sulphides.","exc": false,"tab": false,"src": "p15","page": 2,"o": "Arsenic, antimony and bismuth are found mainly as sulphide minerals."},{"sec": "Occurrence","ids": [23],"t": "Mc: synthetic, radioactive.","exc": false,"tab": false,"src": "p15","page": 2,"o": "Moscovium is a synthetic radioactive element."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [29],"t": "ns^2np^3: filled s and half-filled p, an extra-stable configuration.","exc": false,"tab": false,"src": "p15","page": 2,"o": "The s orbital in these elements is completely filled and p orbitals are half-filled, making their electronic configuration extra stable."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [30],"t": "Covalent and ionic radii increase down the group.","exc": false,"tab": false,"src": "p15","page": 2,"o": "Covalent and ionic (in a particular state) radii increase in size down the group."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [31,32],"t": "**Big radius jump N → P; only small increase As → Bi** (filled d/f).","exc": true,"tab": false,"src": "p15","page": 2,"o": "There is a considerable increase in covalent radius from N to P. However, from As to Bi only a small increase in covalent radius is observed. This is due to the presence of completely filled d and/or f orbitals in heavier members."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [33],"t": "∆iH decreases down the group (size).","exc": false,"tab": false,"src": "p15","page": 2,"o": "Ionisation enthalpy decreases down the group due to gradual increase in atomic size."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [34],"t": "**∆iH of group 15 >> group 14** in the same period (half-filled p, smaller size).","exc": true,"tab": false,"src": "p15","page": 2,"o": "Because of the extra stable half-filled p orbitals electronic configuration and smaller size, the ionisation enthalpy of the group 15 elements is much greater than that of group 14 elements in the corresponding periods."},{"sec": "Electronic configuration, radii, ionisation enthalpy","ids": [35],"t": "∆iH1 < ∆iH2 < ∆iH3.","exc": false,"tab": false,"src": "p15","page": 2,"o": "The order of successive ionisation enthalpies, as expected is ∆iH1 < ∆iH2 < ∆iH3."},{"sec": "Electronegativity and physical properties","ids": [36,37],"t": "EN decreases down the group; small differences among heavier members.","exc": false,"tab": false,"src": "p15","page": 3,"o": "The electronegativity value, in general, decreases down the group with increasing atomic size. However, amongst the heavier elements, the difference is not that much pronounced."},{"sec": "Electronegativity and physical properties","ids": [38,39],"t": "All polyatomic; N2 is a diatomic gas, the rest solids.","exc": false,"tab": false,"src": "p15","page": 3,"o": "All the elements of this group are polyatomic. Dinitrogen is a diatomic gas while all others are solids."},{"sec": "Electronegativity and physical properties","ids": [40],"t": "Metallic character increases down the group.","exc": false,"tab": false,"src": "p15","page": 3,"o": "Metallic character increases down the group."},{"sec": "Electronegativity and physical properties","ids": [41],"t": "N, P non-metals; As, Sb metalloids; Bi metal (∆iH falls, size rises).","exc": false,"tab": false,"src": "p15","page": 3,"o": "Nitrogen and phosphorus are non-metals, arsenic and antimony metalloids and bismuth is a metal. This is due to decrease in ionisation enthalpy and increase in atomic size."},{"sec": "Electronegativity and physical properties","ids": [42],"t": "**b.p. increases down the group; m.p. increases up to As, then decreases to Bi.**","exc": true,"tab": false,"src": "p15","page": 3,"o": "The boiling points, in general, increase from top to bottom in the group but the melting point increases upto arsenic and then decreases upto bismuth."},{"sec": "Electronegativity and physical properties","ids": [43],"t": "**All except N show allotropy.**","exc": true,"tab": false,"src": "p15","page": 3,"o": "Except nitrogen, all the elements show allotropy."},{"sec": "Oxidation states","ids": [44],"t": "Common oxidation states –3, +3, +5.","exc": false,"tab": false,"src": "p15","page": 3,"o": "The common oxidation states of these elements are –3, +3 and +5."},{"sec": "Oxidation states","ids": [45],"t": "–3 tendency decreases down the group (size, metallic character).","exc": false,"tab": false,"src": "p15","page": 3,"o": "The tendency to exhibit –3 oxidation state decreases down the group due to increase in size and metallic character."},{"sec": "Oxidation states","ids": [46],"t": "**Bi hardly forms any –3 compound.**","exc": true,"tab": false,"src": "p15","page": 3,"o": "In fact last member of the group, bismuth hardly forms any compound in –3 oxidation state."},{"sec": "Oxidation states","ids": [47],"t": "+5 stability decreases down the group.","exc": false,"tab": false,"src": "p15","page": 3,"o": "The stability of +5 oxidation state decreases down the group."},{"sec": "Oxidation states","ids": [48],"t": "**Only well-characterised Bi(V) compound: BiF5.** +5 less stable, +3 more stable down the group (inert pair).","exc": true,"tab": false,"src": "p15","page": 3,"o": "The only well characterised Bi(V) compound is BiF5. The stability of +5 oxidation state decreases and that of +3 state increases (due to inert pair effect) down the group."},{"sec": "Oxidation states","ids": [49],"t": "N also shows +1, +2, +4 with oxygen.","exc": false,"tab": false,"src": "p15","page": 3,"o": "Besides +5 oxidation state, nitrogen exhibits +1, +2, +4 oxidation states also when it reacts with oxygen."},{"sec": "Oxidation states","ids": [50],"t": "**N forms no +5 halide**: no d orbitals.","exc": true,"tab": false,"src": "p15","page": 3,"o": "However, it does not form compounds in +5 oxidation state with halogens as nitrogen does not have d-orbitals to accommodate electrons from other elements to form bonds."},{"sec": "Oxidation states","ids": [51],"t": "P shows +1 and +4 in some oxoacids.","exc": false,"tab": false,"src": "p15","page": 3,"o": "Phosphorus also shows +1 and +4 oxidation states in some oxoacids."},{"sec": "Oxidation states","ids": [52,53],"t": "N: all states +1 to +4 disproportionate in acid, e.g. 3HNO2 → HNO3 + H2O + 2NO","exc": false,"tab": false,"src": "p15","page": 3,"o": "In the case of nitrogen, all oxidation states from +1 to +4 tend to disproportionate in acid solution. For example, 3HNO2 → HNO3 + H2O + 2NO"},{"sec": "Oxidation states","ids": [53],"t": "P: nearly all intermediate states disproportionate to +5 and –3 in acid and alkali.","exc": false,"tab": false,"src": "p15","page": 3,"o": "Similarly, in case of phosphorus nearly all intermediate oxidation states disproportionate into +5 and –3 both in alkali and acid."},{"sec": "Oxidation states","ids": [54],"t": "+3 of As, Sb, Bi becomes increasingly stable to disproportionation.","exc": false,"tab": false,"src": "p15","page": 3,"o": "However +3 oxidation state in case of arsenic, antimony and bismuth becomes increasingly stable with respect to disproportionation."},{"sec": "Oxidation states","ids": [55],"t": "**N: max covalency 4** (one s + three p orbitals).","exc": true,"tab": false,"src": "p15","page": 3,"o": "Nitrogen is restricted to a maximum covalency of 4 since only four (one s and three p) orbitals are available for bonding."},{"sec": "Oxidation states","ids": [56],"t": "Heavier members use vacant d orbitals to expand covalence, e.g. PF6^–.","exc": false,"tab": false,"src": "p15","page": 3,"o": "The heavier elements have vacant d orbitals in the outermost shell which can be used for bonding (covalency) and hence, expand their covalence as in PF6^–."},{"sec": "Oxidation states","ids": [700],"t": "Higher positive oxidation state, more polarising power, more covalent bond.","exc": false,"tab": true,"src": "p15","page": 45,"o": "Higher the positive oxidation state of central atom, more will be its polarising power which, in turn, increases the covalent character of bond formed between the central atom and the other atom."},{"sec": "Anomalous properties of nitrogen","ids": [57],"t": "N is anomalous: small size, high EN, high ∆iH, no d orbitals.","exc": true,"tab": false,"src": "p15","page": 3,"o": "Nitrogen differs from the rest of the members of this group due to its small size, high electronegativity, high ionisation enthalpy and non-availability of d orbitals."},{"sec": "Anomalous properties of nitrogen","ids": [58],"t": "**N forms pπ–pπ multiple bonds with itself and with small electronegative atoms (C, O).**","exc": true,"tab": false,"src": "p15","page": 3,"o": "Nitrogen has unique ability to form pπ-pπ multiple bonds with itself and with other elements having small size and high electronegativity (e.g., C, O)."},{"sec": "Anomalous properties of nitrogen","ids": [59],"t": "Heavier members can't (orbitals too large and diffuse).","exc": false,"tab": false,"src": "p15","page": 3,"o": "Heavier elements of this group do not form pπ-pπ bonds as their atomic orbitals are so large and diffuse that they cannot have effective overlapping."},{"sec": "Anomalous properties of nitrogen","ids": [60,61],"t": "So N exists as N≡N (one σ, two π); bond enthalpy 941.4 kJ mol^–1, very high.","exc": false,"tab": false,"src": "p15","page": 3,"o": "Thus, nitrogen exists as a diatomic molecule with a triple bond (one s and two p) between the two atoms. Consequently, its bond enthalpy (941.4 kJ mol^–1) is very high."},{"sec": "Anomalous properties of nitrogen","ids": [62],"t": "P, As, Sb form single E–E bonds; Bi is metallic.","exc": false,"tab": false,"src": "p15","page": 3,"o": "On the contrary, phosphorus, arsenic and antimony form single bonds as P–P, As–As and Sb–Sb while bismuth forms metallic bonds in elemental state."},{"sec": "Anomalous properties of nitrogen","ids": [63,64],"t": "**Single N–N bond is weaker than P–P**: strong lone-pair repulsion at the short bond length.","exc": true,"tab": false,"src": "p15","page": 3,"o": "However, the single N–N bond is weaker than the single P–P bond because of high interelectronic repulsion of the non-bonding electrons, owing to the small bond length."},{"sec": "Anomalous properties of nitrogen","ids": [65],"t": "So N has weaker catenation.","exc": true,"tab": false,"src": "p15","page": 4,"o": "As a result the catenation tendency is weaker in nitrogen."},{"sec": "Anomalous properties of nitrogen","ids": [66],"t": "No d orbitals in N's valence shell.","exc": false,"tab": false,"src": "p15","page": 4,"o": "Another factor which affects the chemistry of nitrogen is the absence of d orbitals in its valence shell."},{"sec": "Anomalous properties of nitrogen","ids": [67],"t": "**N can't form dπ–pπ bonds**; P can (R3P=O, R3P=CH2).","exc": true,"tab": false,"src": "p15","page": 4,"o": "Besides restricting its covalency to four, nitrogen cannot form dπ–pπ bond as the heavier elements can e.g., R3P = O or R3P = CH2 (R = alkyl group)."},{"sec": "Anomalous properties of nitrogen","ids": [68],"t": "P and As form dπ–dπ bonds with transition metals as ligands, e.g. P(C2H5)3, As(C6H5)3.","exc": false,"tab": false,"src": "p15","page": 4,"o": "Phosphorus and arsenic can form dπ–dπ bond also with transition metals when their compounds like P(C2H5)3 and As(C6H5)3 act as ligands."},{"sec": "Anomalous properties of nitrogen","ids": [700],"t": "N≡N: strong pπ–pπ overlap.","exc": false,"tab": true,"src": "p15","page": 45,"o": "Because of strong pπ–pπ overlap resulting into the triple bond, N≡N."},{"sec": "Hydrides EH3","ids": [69],"t": "All form EH3 (E = N, P, As, Sb, Bi).","exc": false,"tab": false,"src": "p15","page": 4,"o": "All the elements of Group 15 form hydrides of the type EH3 where E = N, P, As, Sb or Bi."},{"sec": "Hydrides EH3","ids": [70],"t": "Hydride properties change regularly down the group.","exc": false,"tab": false,"src": "p15","page": 4,"o": "The hydrides show regular gradation in their properties."},{"sec": "Hydrides EH3","ids": [71,72],"t": "**Stability falls NH3 → BiH3** (bond dissociation enthalpy), so reducing character rises.","exc": false,"tab": false,"src": "p15","page": 4,"o": "The stability of hydrides decreases from NH3 to BiH3 which can be observed from their bond dissociation enthalpy. Consequently, the reducing character of the hydrides increases."},{"sec": "Hydrides EH3","ids": [73],"t": "NH3: mild reductant; **BiH3: strongest reducing hydride**.","exc": false,"tab": false,"src": "p15","page": 4,"o": "Ammonia is only a mild reducing agent while BiH3 is the strongest reducing agent amongst all the hydrides."},{"sec": "Hydrides EH3","ids": [74],"t": "**Basicity: NH3 > PH3 > AsH3 > SbH3 > BiH3.**","exc": false,"tab": false,"src": "p15","page": 4,"o": "Basicity also decreases in the order NH3 > PH3 > AsH3 > SbH3 > BiH3."},{"sec": "Hydrides EH3","ids": [74,75],"t": "**NH3 is H-bonded in solid and liquid, so its m.p./b.p. exceed PH3's.**","exc": true,"tab": false,"src": "p15","page": 4,"o": "Due to high electronegativity and small size of nitrogen, NH3 exhibits hydrogen bonding in solid as well as liquid state. Because of this, it has higher melting and boiling points than that of PH3."},{"sec": "Hydrides EH3","ids": [81],"t": "Table 7.2: HEH angle (°) NH3 107.8, PH3 93.6, AsH3 91.8, SbH3 91.3. Boiling point/K NH3 238.5, PH3 185.5, AsH3 210.6, SbH3 254.6, BiH3 290. ∆fH^⊖/kJ mol^–1 NH3 –46.1, PH3 13.4, AsH3 66.4, SbH3 145.1, BiH3 278.","exc": false,"tab": true,"src": "p15","page": 4,"o": "Table 7.2: HEH angle (°) NH3 107.8, PH3 93.6, AsH3 91.8, SbH3 91.3. Boiling point/K NH3 238.5, PH3 185.5, AsH3 210.6, SbH3 254.6, BiH3 290. ∆fH^⊖/kJ mol^–1 NH3 –46.1, PH3 13.4, AsH3 66.4, SbH3 145.1, BiH3 278."},{"sec": "Hydrides EH3","ids": [82,84,85,86],"t": "N has +5 but no pentahalide: n = 2 has only s and p, no d to exceed covalence 4.","exc": false,"tab": false,"src": "p15","page": 5,"o": "Though nitrogen exhibits +5 oxidation state, it does not form pentahalide. Nitrogen with n = 2, has s and p orbitals only. It does not have d orbitals to expand its covalence beyond four. That is why it does not form pentahalide."},{"sec": "Hydrides EH3","ids": [88],"t": "Liquid PH3 is not H-bonded (unlike NH3).","exc": false,"tab": false,"src": "p15","page": 5,"o": "Unlike NH3, PH3 molecules are not associated through hydrogen bonding in liquid state."},{"sec": "Hydrides EH3","ids": [690],"t": "Bond angle NH3 (107.8°) > others: NH3 is sp^3; in heavier hydrides H bonds by nearly pure s–p overlap.","exc": false,"tab": false,"src": "p15","page": 44,"o": "[Hint: Can be explained on the basis of sp3 hybridisation in NH3 and only s–p bonding between hydrogen and other elements of the group]."},{"sec": "Hydrides EH3","ids": [700],"t": "BiH3 is the least stable group 15 hydride.","exc": false,"tab": true,"src": "p15","page": 45,"o": "BiH3 is the least stable among the hydrides of Group 15."},{"sec": "Hydrides EH3","ids": [701],"t": "PH4^+ angle > PH3: PH3's lone pair causes lp–bp repulsion, so angle < 109°28′.","exc": false,"tab": true,"src": "p15","page": 45,"o": "In PH4^+ all the four orbitals are bonded whereas in PH3 there is a lone pair of electrons on P, which is responsible for lone pair-bond pair repulsion in PH3 reducing the bond angle to less than 109° 28′."},{"sec": "Oxides E2O3, E2O5","ids": [75],"t": "Oxides E2O3 and E2O5; the higher oxidation state oxide is more acidic.","exc": false,"tab": false,"src": "p15","page": 4,"o": "All these elements form two types of oxides: E2O3 and E2O5. The oxide in the higher oxidation state of the element is more acidic than that of lower oxidation state."},{"sec": "Oxides E2O3, E2O5","ids": [76],"t": "Acidic character decreases down the group.","exc": false,"tab": false,"src": "p15","page": 4,"o": "Their acidic character decreases down the group."},{"sec": "Oxides E2O3, E2O5","ids": [77],"t": "**E2O3: N, P purely acidic; As, Sb amphoteric; Bi mainly basic.**","exc": false,"tab": false,"src": "p15","page": 4,"o": "The oxides of the type E2O3 of nitrogen and phosphorus are purely acidic, that of arsenic and antimony amphoteric and those of bismuth predominantly basic."},{"sec": "Halides EX3, EX5","ids": [78],"t": "Halides EX3 and EX5; **no NX5** (no d orbitals).","exc": true,"tab": false,"src": "p15","page": 4,"o": "These elements react to form two series of halides: EX3 and EX5. Nitrogen does not form pentahalide due to non-availability of the d orbitals in its valence shell."},{"sec": "Halides EX3, EX5","ids": [79,80],"t": "Pentahalides more covalent than trihalides (+5 vs +3).","exc": false,"tab": false,"src": "p15","page": 4,"o": "Pentahalides are more covalent than trihalides. This is due to the fact that in pentahalides +5 oxidation state exists while in the case of trihalides +3 oxidation state exists."},{"sec": "Halides EX3, EX5","ids": [81,95],"t": "+5 has more polarising power, hence more covalent.","exc": false,"tab": false,"src": "p15","page": 4,"o": "Since elements in +5 oxidation state will have more polarising power than in +3 oxidation state, the covalent character of bonds is more in pentahalides."},{"sec": "Halides EX3, EX5","ids": [96,97],"t": "All trihalides stable **except N's; only NF3 is stable**.","exc": true,"tab": false,"src": "p15","page": 5,"o": "All the trihalides of these elements except those of nitrogen are stable. In case of nitrogen, only NF3 is known to be stable."},{"sec": "Halides EX3, EX5","ids": [98],"t": "Trihalides mostly covalent **except BiF3**.","exc": true,"tab": false,"src": "p15","page": 5,"o": "Trihalides except BiF3 are predominantly covalent in nature."},{"sec": "Binary compounds with metals","ids": [99],"t": "Binary –3 compounds with metals: Ca3N2, Ca3P2, Na3As, Zn3Sb2, Mg3Bi2.","exc": false,"tab": false,"src": "p15","page": 5,"o": "All these elements react with metals to form their binary compounds exhibiting –3 oxidation state, such as, Ca3N2 (calcium nitride) Ca3P2 (calcium phosphide), Na3As (sodium arsenide), Zn3Sb2 (zinc antimonide) and Mg3Bi2 (magnesium bismuthide)."},{"sec": "Dinitrogen","ids": [89],"t": "N2 commercially: liquefaction and fractional distillation of air.","exc": false,"tab": false,"src": "p15","page": 5,"o": "Dinitrogen is produced commercially by the liquefaction and fractional distillation of air."},{"sec": "Dinitrogen","ids": [90],"t": "Liquid N2 (b.p. 77.2 K) distils first, leaving liquid O2 (b.p. 90 K).","exc": false,"tab": false,"src": "p15","page": 5,"o": "Liquid dinitrogen (b.p. 77.2 K) distils out first leaving behind liquid oxygen (b.p. 90 K)."},{"sec": "Dinitrogen","ids": [91],"t": "Lab: aqueous NH4Cl + NaNO2.","exc": false,"tab": false,"src": "p15","page": 5,"o": "In the laboratory, dinitrogen is prepared by treating an aqueous solution of ammonium chloride with sodium nitrite."},{"sec": "Dinitrogen","ids": [92],"t": "NH4Cl(aq) + NaNO2(aq) → N2(g) + 2H2O(l) + NaCl(aq)","exc": false,"tab": false,"src": "p15","page": 5,"o": "NH4Cl(aq) + NaNO2(aq) → N2(g) + 2H2O(l) + NaCl(aq)"},{"sec": "Dinitrogen","ids": [92],"t": "NO and HNO3 impurities removed by aqueous H2SO4 containing K2Cr2O7.","exc": false,"tab": false,"src": "p15","page": 5,"o": "Small amounts of NO and HNO3 are also formed in this reaction; these impurities can be removed by passing the gas through aqueous sulphuric acid containing potassium dichromate."},{"sec": "Dinitrogen","ids": [93,94],"t": "(NH4)2Cr2O7 → N2 + 4H2O + Cr2O3 (heat)","exc": false,"tab": false,"src": "p15","page": 5,"o": "It can also be obtained by the thermal decomposition of ammonium dichromate. (NH4)2Cr2O7 → N2 + 4H2O + Cr2O3 (heat)"},{"sec": "Dinitrogen","ids": [94,95],"t": "**Very pure N2**: thermal decomposition of Na or Ba azide. Ba(N3)2 → Ba + 3N2","exc": false,"tab": false,"src": "p15","page": 5,"o": "Very pure nitrogen can be obtained by the thermal decomposition of sodium or barium azide. Ba(N3)2 → Ba + 3N2"},{"sec": "Dinitrogen","ids": [101],"t": "N2: colourless, odourless, tasteless, non-toxic.","exc": false,"tab": false,"src": "p15","page": 6,"o": "Dinitrogen is a colourless, odourless, tasteless and non-toxic gas."},{"sec": "Dinitrogen","ids": [102],"t": "Very low water solubility (23.2 cm^3/L at 273 K, 1 bar); low f.p. and b.p.","exc": false,"tab": false,"src": "p15","page": 6,"o": "It has a very low solubility in water (23.2 cm^3 per litre of water at 273 K and 1 bar pressure) and low freezing and boiling points."},{"sec": "Dinitrogen","ids": [103,104],"t": "Inert at room temperature (very high N≡N bond enthalpy); reactivity rises fast with T.","exc": false,"tab": false,"src": "p15","page": 6,"o": "Dinitrogen is rather inert at room temperature because of the high bond enthalpy of N≡N bond. Reactivity, however, increases rapidly with rise in temperature."},{"sec": "Dinitrogen","ids": [105],"t": "At high T: ionic nitrides with some metals, covalent nitrides with non-metals.","exc": false,"tab": false,"src": "p15","page": 6,"o": "At higher temperatures, it directly combines with some metals to form predominantly ionic nitrides and with non-metals, covalent nitrides."},{"sec": "Dinitrogen","ids": [106],"t": "6Li + N2 → 2Li3N; 3Mg + N2 → Mg3N2 (heat)","exc": false,"tab": false,"src": "p15","page": 6,"o": "A few typical reactions are: 6Li + N2 → 2Li3N (heat); 3Mg + N2 → Mg3N2 (heat)"},{"sec": "Dinitrogen","ids": [106],"t": "Haber process: N2(g) + 3H2(g) ⇌ 2NH3(g) at ~773 K with catalyst; ∆fH = –46.1 kJ mol^–1","exc": false,"tab": false,"src": "p15","page": 6,"o": "It combines with hydrogen at about 773 K in the presence of a catalyst (Haber's Process) to form ammonia: N2(g) + 3H2(g) ⇌ 2NH3(g); ∆fH = –46.1 kJ mol^–1"},{"sec": "Dinitrogen","ids": [106],"t": "N2 + O2 ⇌ 2NO only at very high T (~2000 K).","exc": false,"tab": false,"src": "p15","page": 6,"o": "Dinitrogen combines with dioxygen only at very high temperature (at about 2000 K) to form nitric oxide, NO. N2 + O2(g) ⇌ 2NO(g) (heat)"},{"sec": "Dinitrogen","ids": [106],"t": "N2 uses: NH3 and N-containing chemicals (e.g. calcium cyanamide).","exc": false,"tab": false,"src": "p15","page": 6,"o": "The main use of dinitrogen is in the manufacture of ammonia and other industrial chemicals containing nitrogen, (e.g., calcium cyanamide)."},{"sec": "Dinitrogen","ids": [107],"t": "Inert atmosphere (iron and steel industry, diluent for reactive chemicals).","exc": false,"tab": false,"src": "p15","page": 6,"o": "It also finds use where an inert atmosphere is required (e.g., in iron and steel industry, inert diluent for reactive chemicals)."},{"sec": "Dinitrogen","ids": [108],"t": "Liquid N2: refrigerant for biological materials, food, cryosurgery.","exc": false,"tab": false,"src": "p15","page": 6,"o": "Liquid dinitrogen is used as a refrigerant to preserve biological materials, food items and in cryosurgery."},{"sec": "Dinitrogen","ids": [110],"t": "2NaN3 → 2Na + 3N2","exc": false,"tab": false,"src": "p15","page": 6,"o": "Thermal decomposition of sodium azide gives dinitrogen gas. 2NaN3 → 2Na + 3N2"},{"sec": "Ammonia","ids": [100],"t": "NH3 in air and soil from decay of nitrogenous matter (e.g. urea).","exc": false,"tab": false,"src": "p15","page": 6,"o": "Ammonia is present in small quantities in air and soil where it is formed by the decay of nitrogenous organic matter e.g., urea."},{"sec": "Ammonia","ids": [101],"t": "NH2CONH2 + 2H2O → (NH4)2CO3 ⇌ 2NH3 + H2O + CO2","exc": false,"tab": true,"src": "p15","page": 6,"o": "NH2CONH2 + 2H2O → (NH4)2CO3 ⇌ 2NH3 + H2O + CO2"},{"sec": "Ammonia","ids": [101],"t": "Small scale: ammonium salts + caustic soda or slaked lime.","exc": false,"tab": false,"src": "p15","page": 6,"o": "On a small scale ammonia is obtained from ammonium salts which decompose when treated with caustic soda or calcium hydroxide."},{"sec": "Ammonia","ids": [101],"t": "2NH4Cl + Ca(OH)2 → 2NH3 + 2H2O + CaCl2; (NH4)2SO4 + 2NaOH → 2NH3 + 2H2O + Na2SO4","exc": false,"tab": false,"src": "p15","page": 6,"o": "2NH4Cl + Ca(OH)2 → 2NH3 + 2H2O + CaCl2; (NH4)2SO4 + 2NaOH → 2NH3 + 2H2O + Na2SO4"},{"sec": "Ammonia","ids": [111],"t": "NH3: colourless, pungent.","exc": false,"tab": false,"src": "p15","page": 7,"o": "Ammonia is a colourless gas with a pungent odour."},{"sec": "Ammonia","ids": [112],"t": "f.p. 198.4 K, b.p. 239.7 K.","exc": false,"tab": false,"src": "p15","page": 7,"o": "Its freezing and boiling points are 198.4 and 239.7 K respectively."},{"sec": "Ammonia","ids": [113],"t": "H-bonded in solid and liquid, so m.p./b.p. higher than expected from molar mass.","exc": false,"tab": false,"src": "p15","page": 7,"o": "In the solid and liquid states, it is associated through hydrogen bonds as in the case of water and that accounts for its higher melting and boiling points than expected on the basis of its molecular mass."},{"sec": "Ammonia","ids": [114],"t": "**NH3: trigonal pyramidal**, N at apex; 3 bond pairs, 1 lone pair.","exc": false,"tab": false,"src": "p15","page": 7,"o": "The ammonia molecule is trigonal pyramidal with the nitrogen atom at the apex. It has three bond pairs and one lone pair of electrons as shown in the structure."},{"sec": "Ammonia","ids": [115,116],"t": "Very soluble; aqueous NH3 is weakly basic (OH^–).","exc": false,"tab": false,"src": "p15","page": 7,"o": "Ammonia gas is highly soluble in water. Its aqueous solution is weakly basic due to the formation of OH^– ions."},{"sec": "Ammonia","ids": [117],"t": "NH3(g) + H2O(l) ⇌ NH4^+(aq) + OH^–(aq)","exc": false,"tab": false,"src": "p15","page": 7,"o": "NH3(g) + H2O(l) ⇌ NH4^+(aq) + OH^–(aq)"},{"sec": "Ammonia","ids": [117],"t": "Forms ammonium salts (NH4Cl, (NH4)2SO4); as a weak base it precipitates metal hydroxides (or hydrated oxides).","exc": false,"tab": false,"src": "p15","page": 7,"o": "It forms ammonium salts with acids, e.g., NH4Cl, (NH4)2SO4, etc. As a weak base, it precipitates the hydroxides (hydrated oxides in case of some metals) of many metals from their salt solutions."},{"sec": "Ammonia","ids": [118],"t": "ZnSO4(aq) + 2NH4OH(aq) → Zn(OH)2(s) (white ppt) + (NH4)2SO4(aq)","exc": false,"tab": true,"src": "p15","page": 7,"o": "ZnSO4(aq) + 2NH4OH(aq) → Zn(OH)2(s) (white ppt) + (NH4)2SO4(aq)"},{"sec": "Ammonia","ids": [118,119],"t": "FeCl3(aq) + NH4OH(aq) → Fe2O3.xH2O(s) (brown ppt) + NH4Cl(aq)","exc": false,"tab": true,"src": "p15","page": 7,"o": "FeCl3(aq) + NH4OH(aq) → Fe2O3.xH2O(s) (brown ppt) + NH4Cl(aq)"},{"sec": "Ammonia","ids": [119,120],"t": "Large scale: Haber process. N2(g) + 3H2(g) ⇌ 2NH3(g); ∆fH = –46.1 kJ mol^–1","exc": false,"tab": false,"src": "p15","page": 7,"o": "On a large scale, ammonia is manufactured by Haber's process. N2(g) + 3H2(g) ⇌ 2NH3(g); ∆fH = –46.1 kJ mol^–1"},{"sec": "Ammonia","ids": [120],"t": "High pressure favours NH3 (Le Chatelier).","exc": false,"tab": false,"src": "p15","page": 7,"o": "In accordance with Le Chatelier's principle, high pressure would favour the formation of ammonia."},{"sec": "Ammonia","ids": [121],"t": "**Optimum: ~200 atm, ~700 K, iron oxide catalyst with a little K2O and Al2O3** (faster approach to equilibrium).","exc": false,"tab": false,"src": "p15","page": 7,"o": "The optimum conditions for the production of ammonia are a pressure of 200 × 10^5 Pa (about 200 atm), a temperature of ~ 700 K and the use of a catalyst such as iron oxide with small amounts of K2O and Al2O3 to increase the rate of attainment of equilibrium."},{"sec": "Ammonia","ids": [123],"t": "Earlier catalyst: Fe with Mo as promoter.","exc": false,"tab": false,"src": "p15","page": 7,"o": "Earlier, iron was used as a catalyst with molybdenum as a promoter."},{"sec": "Ammonia","ids": [125],"t": "N in NH3 has a lone pair available for donation.","exc": false,"tab": false,"src": "p15","page": 8,"o": "Nitrogen atom in NH3 has one lone pair of electrons which is available for donation."},{"sec": "Ammonia","ids": [126],"t": "NH3 uses: fertilisers (NH4NO3, urea, ammonium phosphate, (NH4)2SO4); HNO3 manufacture.","exc": false,"tab": false,"src": "p15","page": 8,"o": "Ammonia is used to produce various nitrogenous fertilisers (ammonium nitrate, urea, ammonium phosphate and ammonium sulphate) and in the manufacture of some inorganic nitrogen compounds, the most important one being nitric acid."},{"sec": "Ammonia","ids": [127],"t": "Liquid NH3: refrigerant.","exc": false,"tab": false,"src": "p15","page": 8,"o": "Liquid ammonia is also used as a refrigerant."},{"sec": "Ammonia","ids": [130],"t": "The lone pair makes NH3 a Lewis base.","exc": false,"tab": false,"src": "p15","page": 8,"o": "The presence of a lone pair of electrons on the nitrogen atom of the ammonia molecule makes it a Lewis base."},{"sec": "Ammonia","ids": [131],"t": "Complex formation detects metal ions such as Cu^2+ and Ag^+.","exc": false,"tab": false,"src": "p15","page": 8,"o": "It donates the electron pair and forms linkage with metal ions and the formation of such complex compounds finds applications in detection of metal ions such as Cu^2+, Ag^+:"},{"sec": "Ammonia","ids": [131],"t": "Cu^2+(aq) (blue) + 4NH3(aq) ⇌ [Cu(NH3)4]^2+(aq) (deep blue)","exc": false,"tab": true,"src": "p15","page": 8,"o": "Cu^2+(aq) (blue) + 4NH3(aq) ⇌ [Cu(NH3)4]^2+(aq) (deep blue)"},{"sec": "Ammonia","ids": [131],"t": "Ag^+(aq) (colourless) + Cl^–(aq) → AgCl(s) (white ppt); AgCl(s) (white ppt) + 2NH3(aq) → [Ag(NH3)2]Cl(aq) (colourless)","exc": false,"tab": true,"src": "p15","page": 8,"o": "Ag^+(aq) (colourless) + Cl^–(aq) → AgCl(s) (white ppt); AgCl(s) (white ppt) + 2NH3(aq) → [Ag(NH3)2]Cl(aq) (colourless)"},{"sec": "Oxides of nitrogen","ids": [128],"t": "N forms oxides in many oxidation states.","exc": false,"tab": false,"src": "p15","page": 8,"o": "Nitrogen forms a number of oxides in different oxidation states."},{"sec": "Oxides of nitrogen","ids": [130],"t": "Table 7.3: Dinitrogen oxide N2O, +1, [Nitrogen(I) oxide]: NH4NO3 → N2O + 2H2O (heat); colourless gas, neutral.","exc": false,"tab": true,"src": "p15","page": 8,"o": "Table 7.3: Dinitrogen oxide N2O, +1, [Nitrogen(I) oxide]: NH4NO3 → N2O + 2H2O (heat); colourless gas, neutral."},{"sec": "Oxides of nitrogen","ids": [130],"t": "Table 7.3: Nitrogen monoxide NO, +2, [Nitrogen(II) oxide]: 2NaNO2 + 2FeSO4 + 3H2SO4 → Fe2(SO4)3 + 2NaHSO4 + 2H2O + 2NO; colourless gas, neutral.","exc": false,"tab": true,"src": "p15","page": 8,"o": "Table 7.3: Nitrogen monoxide NO, +2, [Nitrogen(II) oxide]: 2NaNO2 + 2FeSO4 + 3H2SO4 → Fe2(SO4)3 + 2NaHSO4 + 2H2O + 2NO; colourless gas, neutral."},{"sec": "Oxides of nitrogen","ids": [133],"t": "Table 7.3: Dinitrogen trioxide N2O3, +3, [Nitrogen(III) oxide]: 2NO + N2O4 → 2N2O3 (250 K); blue solid, acidic.","exc": false,"tab": true,"src": "p15","page": 9,"o": "Table 7.3: Dinitrogen trioxide N2O3, +3, [Nitrogen(III) oxide]: 2NO + N2O4 → 2N2O3 (250 K); blue solid, acidic."},{"sec": "Oxides of nitrogen","ids": [133],"t": "Table 7.3: Nitrogen dioxide NO2, +4, [Nitrogen(IV) oxide]: 2Pb(NO3)2 → 4NO2 + 2PbO + O2 (673 K); brown gas, acidic.","exc": false,"tab": true,"src": "p15","page": 9,"o": "Table 7.3: Nitrogen dioxide NO2, +4, [Nitrogen(IV) oxide]: 2Pb(NO3)2 → 4NO2 + 2PbO + O2 (673 K); brown gas, acidic."},{"sec": "Oxides of nitrogen","ids": [133],"t": "Table 7.3: Dinitrogen tetroxide N2O4, +4, [Nitrogen(IV) oxide]: 2NO2 ⇌ N2O4 (cool / heat); colourless solid/liquid, acidic.","exc": false,"tab": true,"src": "p15","page": 9,"o": "Table 7.3: Dinitrogen tetroxide N2O4, +4, [Nitrogen(IV) oxide]: 2NO2 ⇌ N2O4 (cool / heat); colourless solid/liquid, acidic."},{"sec": "Oxides of nitrogen","ids": [133],"t": "Table 7.3: Dinitrogen pentoxide N2O5, +5, [Nitrogen(V) oxide]: 4HNO3 + P4O10 → 4HPO3 + 2N2O5; colourless solid, acidic.","exc": false,"tab": true,"src": "p15","page": 9,"o": "Table 7.3: Dinitrogen pentoxide N2O5, +5, [Nitrogen(V) oxide]: 4HNO3 + P4O10 → 4HPO3 + 2N2O5; colourless solid, acidic."},{"sec": "Oxides of nitrogen","ids": [143,144,145],"t": "**NO2 is an odd-electron molecule**; it dimerises to stable N2O4 (even electrons).","exc": false,"tab": false,"src": "p15","page": 10,"o": "NO2 contains odd number of valence electrons. It behaves as a typical odd molecule. On dimerisation, it is converted to stable N2O4 molecule with even number of electrons."},{"sec": "Oxides of nitrogen","ids": [651],"t": "Nitrogen oxides have resonance structures with multiple bonds.","exc": false,"tab": false,"src": "p15","page": 43,"o": "These oxides have resonating structures and have multiple bonds."},{"sec": "Oxides of nitrogen","ids": [700],"t": "N2O5 structure shows N has covalence 4.","exc": false,"tab": true,"src": "p15","page": 45,"o": "From the structure of N2O5 it is evident that covalence of nitrogen is four."},{"sec": "Nitric acid","ids": [134],"t": "Lab HNO3: NaNO3 (or KNO3) + conc. H2SO4 heated in a glass retort. NaNO3 + H2SO4 → NaHSO4 + HNO3","exc": false,"tab": false,"src": "p15","page": 10,"o": "In the laboratory, nitric acid is prepared by heating KNO3 or NaNO3 and concentrated H2SO4 in a glass retort. NaNO3 + H2SO4 → NaHSO4 + HNO3"},{"sec": "Nitric acid","ids": [134,135],"t": "**Ostwald process**: catalytic oxidation of NH3 by air.","exc": false,"tab": false,"src": "p15","page": 10,"o": "On a large scale it is prepared mainly by Ostwald's process. This method is based upon catalytic oxidation of NH3 by atmospheric oxygen."},{"sec": "Nitric acid","ids": [136],"t": "4NH3(g) + 5O2(g) (from air) → 4NO(g) + 6H2O(g) (Pt/Rh gauge catalyst, 500 K, 9 bar)","exc": false,"tab": true,"src": "p15","page": 10,"o": "4NH3(g) + 5O2(g) (from air) → 4NO(g) + 6H2O(g) (Pt/Rh gauge catalyst, 500 K, 9 bar)"},{"sec": "Nitric acid","ids": [136],"t": "2NO(g) + O2(g) ⇌ 2NO2(g)","exc": false,"tab": false,"src": "p15","page": 10,"o": "Nitric oxide thus formed combines with oxygen giving NO2. 2NO(g) + O2(g) ⇌ 2NO2(g)"},{"sec": "Nitric acid","ids": [136],"t": "3NO2(g) + H2O(l) → 2HNO3(aq) + NO(g)","exc": false,"tab": false,"src": "p15","page": 10,"o": "Nitrogen dioxide so formed, dissolves in water to give HNO3. 3NO2(g) + H2O(l) → 2HNO3(aq) + NO(g)"},{"sec": "Nitric acid","ids": [136],"t": "NO is recycled; aqueous HNO3 concentrated by distillation to ~68%.","exc": false,"tab": false,"src": "p15","page": 10,"o": "NO thus formed is recycled and the aqueous HNO3 can be concentrated by distillation upto ~ 68% by mass."},{"sec": "Nitric acid","ids": [137],"t": "98% HNO3 by dehydration with conc. H2SO4.","exc": false,"tab": false,"src": "p15","page": 10,"o": "Further concentration to 98% can be achieved by dehydration with concentrated H2SO4."},{"sec": "Nitric acid","ids": [137],"t": "HNO3: colourless liquid, f.p. 231.4 K, b.p. 355.6 K.","exc": false,"tab": false,"src": "p15","page": 10,"o": "It is a colourless liquid (f.p. 231.4 K and b.p. 355.6 K)."},{"sec": "Nitric acid","ids": [138],"t": "Lab-grade HNO3 ≈ 68% by mass, specific gravity 1.504.","exc": false,"tab": false,"src": "p15","page": 10,"o": "Laboratory grade nitric acid contains ~ 68% of the HNO3 by mass and has a specific gravity of 1.504."},{"sec": "Nitric acid","ids": [139],"t": "Gaseous HNO3 is planar.","exc": false,"tab": false,"src": "p15","page": 10,"o": "In the gaseous state, HNO3 exists as a planar molecule with the structure as shown."},{"sec": "Nitric acid","ids": [140,141],"t": "Strong acid: HNO3(aq) + H2O(l) → H3O^+(aq) + NO3^–(aq)","exc": false,"tab": false,"src": "p15","page": 10,"o": "In aqueous solution, nitric acid behaves as a strong acid giving hydronium and nitrate ions. HNO3(aq) + H2O(l) → H3O^+(aq) + NO3^–(aq)"},{"sec": "Nitric acid","ids": [141],"t": "Conc. HNO3 is a strong oxidant; attacks most metals **except noble metals (Au, Pt)**.","exc": false,"tab": false,"src": "p15","page": 10,"o": "Concentrated nitric acid is a strong oxidising agent and attacks most metals except noble metals such as gold and platinum."},{"sec": "Nitric acid","ids": [145,146],"t": "N oxoacids: H2N2O2 (hyponitrous), HNO2 (nitrous), HNO3 (nitric).","exc": false,"tab": false,"src": "p15","page": 10,"o": "Nitrogen forms oxoacids such as H2N2O2 (hyponitrous acid), HNO2 (nitrous acid) and HNO3 (nitric acid). Amongst them HNO3 is the most important."},{"sec": "Nitric acid","ids": [147],"t": "Products depend on acid concentration, temperature and the substance oxidised.","exc": false,"tab": false,"src": "p15","page": 11,"o": "The products of oxidation depend upon the concentration of the acid, temperature and the nature of the material undergoing oxidation."},{"sec": "Nitric acid","ids": [147],"t": "3Cu + 8HNO3(dilute) → 3Cu(NO3)2 + 2NO + 4H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "3Cu + 8HNO3(dilute) → 3Cu(NO3)2 + 2NO + 4H2O"},{"sec": "Nitric acid","ids": [147],"t": "Cu + 4HNO3(conc.) → Cu(NO3)2 + 2NO2 + 2H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "Cu + 4HNO3(conc.) → Cu(NO3)2 + 2NO2 + 2H2O"},{"sec": "Nitric acid","ids": [147],"t": "Zn: **dilute HNO3 gives N2O, concentrated gives NO2**.","exc": false,"tab": false,"src": "p15","page": 11,"o": "Zinc reacts with dilute nitric acid to give N2O and with concentrated acid to give NO2."},{"sec": "Nitric acid","ids": [147],"t": "4Zn + 10HNO3(dilute) → 4Zn(NO3)2 + 5H2O + N2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "4Zn + 10HNO3(dilute) → 4Zn(NO3)2 + 5H2O + N2O"},{"sec": "Nitric acid","ids": [147],"t": "Zn + 4HNO3(conc.) → Zn(NO3)2 + 2H2O + 2NO2","exc": false,"tab": false,"src": "p15","page": 11,"o": "Zn + 4HNO3(conc.) → Zn(NO3)2 + 2H2O + 2NO2"},{"sec": "Nitric acid","ids": [147],"t": "**Cr and Al don't dissolve in conc. HNO3 (passive oxide film).**","exc": true,"tab": false,"src": "p15","page": 11,"o": "Some metals (e.g., Cr, Al) do not dissolve in concentrated nitric acid because of the formation of a passive film of oxide on the surface."},{"sec": "Nitric acid","ids": [148,149],"t": "Conc. HNO3 oxidises I2 → HIO3, C → CO2, S → H2SO4, P → H3PO4.","exc": false,"tab": false,"src": "p15","page": 11,"o": "Concentrated nitric acid also oxidises non–metals and their compounds. Iodine is oxidised to iodic acid, carbon to carbon dioxide, sulphur to H2SO4, and phosphorus to phosphoric acid."},{"sec": "Nitric acid","ids": [150],"t": "I2 + 10HNO3 → 2HIO3 + 10NO2 + 4H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "I2 + 10HNO3 → 2HIO3 + 10NO2 + 4H2O"},{"sec": "Nitric acid","ids": [150],"t": "C + 4HNO3 → CO2 + 2H2O + 4NO2","exc": false,"tab": false,"src": "p15","page": 11,"o": "C + 4HNO3 → CO2 + 2H2O + 4NO2"},{"sec": "Nitric acid","ids": [150],"t": "S8 + 48HNO3 → 8H2SO4 + 48NO2 + 16H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "S8 + 48HNO3 → 8H2SO4 + 48NO2 + 16H2O"},{"sec": "Nitric acid","ids": [150],"t": "P4 + 20HNO3 → 4H3PO4 + 20NO2 + 4H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "P4 + 20HNO3 → 4H3PO4 + 20NO2 + 4H2O"},{"sec": "Nitric acid","ids": [150],"t": "**Brown ring test**: Fe^2+ reduces nitrate to NO, which forms a brown complex with Fe^2+.","exc": false,"tab": false,"src": "p15","page": 11,"o": "The familiar brown ring test for nitrates depends on the ability of Fe^2+ to reduce nitrates to nitric oxide, which reacts with Fe^2+ to form a brown coloured complex."},{"sec": "Nitric acid","ids": [150],"t": "Dilute FeSO4 added to the nitrate solution, then conc. H2SO4 poured carefully down the side.","exc": false,"tab": false,"src": "p15","page": 11,"o": "The test is usually carried out by adding dilute ferrous sulphate solution to an aqueous solution containing nitrate ion, and then carefully adding concentrated sulphuric acid along the sides of the test tube."},{"sec": "Nitric acid","ids": [151],"t": "Brown ring at the interface confirms NO3^-.","exc": false,"tab": false,"src": "p15","page": 11,"o": "A brown ring at the interface between the solution and sulphuric acid layers indicates the presence of nitrate ion in solution."},{"sec": "Nitric acid","ids": [152],"t": "NO3^- + 3Fe^2+ + 4H^+ → NO + 3Fe^3+ + 2H2O","exc": false,"tab": false,"src": "p15","page": 11,"o": "NO3^- + 3Fe^2+ + 4H^+ → NO + 3Fe^3+ + 2H2O"},{"sec": "Nitric acid","ids": [152],"t": "[Fe(H2O)6]^2+ + NO → [Fe(H2O)5(NO)]^2+ + H2O (brown)","exc": false,"tab": true,"src": "p15","page": 11,"o": "[Fe(H2O)6]^2+ + NO → [Fe(H2O)5(NO)]^2+ + H2O (brown)"},{"sec": "Nitric acid","ids": [152],"t": "HNO3 uses: NH4NO3 fertiliser; nitrates for explosives and pyrotechnics.","exc": false,"tab": false,"src": "p15","page": 11,"o": "The major use of nitric acid is in the manufacture of ammonium nitrate for fertilisers and other nitrates for use in explosives and pyrotechnics."},{"sec": "Nitric acid","ids": [153],"t": "Nitroglycerin, TNT and other nitro compounds.","exc": false,"tab": false,"src": "p15","page": 11,"o": "It is also used for the preparation of nitroglycerin, trinitrotoluene and other organic nitro compounds."},{"sec": "Nitric acid","ids": [154],"t": "Pickling stainless steel, etching metals, oxidiser in rocket fuels.","exc": false,"tab": false,"src": "p15","page": 11,"o": "Other major uses are in the pickling of stainless steel, etching of metals and as an oxidiser in rocket fuels."},{"sec": "Nitric acid","ids": [653],"t": "HNO3: strong monobasic acid and powerful oxidant.","exc": false,"tab": false,"src": "p15","page": 43,"o": "HNO3 is an important industrial chemical. It is a strong monobasic acid and is a powerful oxidising agent."},{"sec": "Phosphorus: allotropic forms","ids": [155],"t": "Main allotropes of P: white, red, black.","exc": false,"tab": false,"src": "p15","page": 11,"o": "Phosphorus is found in many allotropic forms, the important ones being white, red and black."},{"sec": "Phosphorus: allotropic forms","ids": [156],"t": "White P: translucent, waxy.","exc": false,"tab": false,"src": "p15","page": 11,"o": "White phosphorus is a translucent white waxy solid."},{"sec": "Phosphorus: allotropic forms","ids": [157],"t": "White P: poisonous; insoluble in water, soluble in CS2; **glows in the dark (chemiluminescence)**.","exc": false,"tab": false,"src": "p15","page": 11,"o": "It is poisonous, insoluble in water but soluble in carbon disulphide and glows in dark (chemiluminescence)."},{"sec": "Phosphorus: allotropic forms","ids": [158],"t": "White P + boiling NaOH (inert atmosphere) gives PH3.","exc": false,"tab": false,"src": "p15","page": 11,"o": "It dissolves in boiling NaOH solution in an inert atmosphere giving PH3."},{"sec": "Phosphorus: allotropic forms","ids": [158],"t": "P4 + 3NaOH + 3H2O → PH3 + 3NaH2PO2 (sodium hypophosphite)","exc": false,"tab": true,"src": "p15","page": 11,"o": "P4 + 3NaOH + 3H2O → PH3 + 3NaH2PO2 (sodium hypophosphite)"},{"sec": "Phosphorus: allotropic forms","ids": [159],"t": "**White P is least stable and most reactive: angular strain in P4 (60° angles).**","exc": true,"tab": false,"src": "p15","page": 12,"o": "White phosphorus is less stable and therefore, more reactive than the other solid phases under normal conditions because of angular strain in the P4 molecule where the angles are only 60°."},{"sec": "Phosphorus: allotropic forms","ids": [160],"t": "Catches fire in air, giving dense white fumes of P4O10. P4 + 5O2 → P4O10","exc": false,"tab": false,"src": "p15","page": 12,"o": "It readily catches fire in air to give dense white fumes of P4O10. P4 + 5O2 → P4O10"},{"sec": "Phosphorus: allotropic forms","ids": [160],"t": "Discrete tetrahedral P4 molecules.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It consists of discrete tetrahedral P4 molecule."},{"sec": "Phosphorus: allotropic forms","ids": [161],"t": "Red P: white P heated at 573 K in an inert atmosphere for several days.","exc": false,"tab": false,"src": "p15","page": 12,"o": "Red phosphorus is obtained by heating white phosphorus at 573K in an inert atmosphere for several days."},{"sec": "Phosphorus: allotropic forms","ids": [162],"t": "Red P under high pressure gives black P phases.","exc": false,"tab": false,"src": "p15","page": 12,"o": "When red phosphorus is heated under high pressure, a series of phases of black phosphorus is formed."},{"sec": "Phosphorus: allotropic forms","ids": [163],"t": "Red P: iron-grey lustre.","exc": false,"tab": false,"src": "p15","page": 12,"o": "Red phosphorus possesses iron grey lustre."},{"sec": "Phosphorus: allotropic forms","ids": [164],"t": "Red P: odourless, non-poisonous, insoluble in water and CS2.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It is odourless, nonpoisonous and insoluble in water as well as in carbon disulphide."},{"sec": "Phosphorus: allotropic forms","ids": [165,166],"t": "Red P is much less reactive than white P; doesn't glow.","exc": false,"tab": false,"src": "p15","page": 12,"o": "Chemically, red phosphorus is much less reactive than white phosphorus. It does not glow in the dark."},{"sec": "Phosphorus: allotropic forms","ids": [167],"t": "**Red P is polymeric**: chains of P4 tetrahedra.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It is polymeric, consisting of chains of P4 tetrahedra linked together."},{"sec": "Phosphorus: allotropic forms","ids": [168],"t": "α-black P: red P heated in a sealed tube at 803 K; sublimes in air; monoclinic or rhombohedral crystals.","exc": false,"tab": false,"src": "p15","page": 12,"o": "Black phosphorus has two forms α-black phosphorus and β-black phosphorus. α-Black phosphorus is formed when red phosphorus is heated in a sealed tube at 803K. It can be sublimed in air and has opaque monoclinic or rhombohedral crystals."},{"sec": "Phosphorus: allotropic forms","ids": [169,170],"t": "α-black P doesn't oxidise in air. β-black P: white P at 473 K under high pressure; doesn't burn in air up to 673 K.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It does not oxidise in air. β-Black phosphorus is prepared by heating white phosphorus at 473 K under high pressure. It does not burn in air upto 673 K."},{"sec": "Phosphine","ids": [170],"t": "PH3: Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3; Ca3P2 + 6HCl → 3CaCl2 + 2PH3","exc": false,"tab": false,"src": "p15","page": 12,"o": "Phosphine is prepared by the reaction of calcium phosphide with water or dilute HCl. Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3; Ca3P2 + 6HCl → 3CaCl2 + 2PH3"},{"sec": "Phosphine","ids": [170],"t": "Lab PH3: white P + conc. NaOH, heated under CO2.","exc": false,"tab": false,"src": "p15","page": 12,"o": "In the laboratory, it is prepared by heating white phosphorus with concentrated NaOH solution in an inert atmosphere of CO2."},{"sec": "Phosphine","ids": [170],"t": "**Pure PH3 is not inflammable**; it becomes inflammable due to P2H4 or P4 vapour impurity.","exc": true,"tab": false,"src": "p15","page": 12,"o": "When pure, it is non inflammable but becomes inflammable owing to the presence of P2H4 or P4 vapours."},{"sec": "Phosphine","ids": [171],"t": "Purified via PH4I (absorbed in HI), then KOH: PH4I + KOH → KI + H2O + PH3","exc": false,"tab": false,"src": "p15","page": 12,"o": "To purify it from the impurities, it is absorbed in HI to form phosphonium iodide (PH4I) which on treating with KOH gives off phosphine. PH4I + KOH → KI + H2O + PH3"},{"sec": "Phosphine","ids": [171],"t": "PH3: colourless, rotten-fish smell, highly poisonous.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It is a colourless gas with rotten fish smell and is highly poisonous."},{"sec": "Phosphine","ids": [172],"t": "Explodes with traces of oxidants (HNO3, Cl2, Br2 vapour).","exc": false,"tab": false,"src": "p15","page": 12,"o": "It explodes in contact with traces of oxidising agents like HNO3, Cl2 and Br2 vapours."},{"sec": "Phosphine","ids": [173],"t": "Slightly soluble in water.","exc": false,"tab": false,"src": "p15","page": 12,"o": "It is slightly soluble in water."},{"sec": "Phosphine","ids": [174],"t": "Aqueous PH3 decomposes in light to red P and H2.","exc": false,"tab": false,"src": "p15","page": 12,"o": "The solution of PH3 in water decomposes in presence of light giving red phosphorus and H2."},{"sec": "Phosphine","ids": [174,178],"t": "With CuSO4 or HgCl2 solution gives phosphides.","exc": false,"tab": false,"src": "p15","page": 12,"o": "When absorbed in copper sulphate or mercuric chloride solution, the corresponding phosphides are obtained."},{"sec": "Phosphine","ids": [176],"t": "Spontaneous combustion of PH3: Holme's signals.","exc": false,"tab": false,"src": "p15","page": 13,"o": "The spontaneous combustion of phosphine is technically used in Holme's signals."},{"sec": "Phosphine","ids": [177],"t": "Containers of CaC2 and Ca3P2 pierced and thrown into the sea; evolved gases burn as a signal; also smoke screens.","exc": false,"tab": false,"src": "p15","page": 13,"o": "Containers containing calcium carbide and calcium phosphide are pierced and thrown in the sea when the gases evolved burn and serve as a signal. It is also used in smoke screens."},{"sec": "Phosphine","ids": [178],"t": "3CuSO4 + 2PH3 → Cu3P2 + 3H2SO4; 3HgCl2 + 2PH3 → Hg3P2 + 6HCl","exc": false,"tab": false,"src": "p15","page": 13,"o": "3CuSO4 + 2PH3 → Cu3P2 + 3H2SO4; 3HgCl2 + 2PH3 → Hg3P2 + 6HCl"},{"sec": "Phosphine","ids": [178],"t": "PH3 is weakly basic; forms phosphonium salts: PH3 + HBr → PH4Br","exc": false,"tab": false,"src": "p15","page": 13,"o": "Phosphine is weakly basic and like ammonia, gives phosphonium compounds with acids e.g., PH3 + HBr → PH4Br"},{"sec": "Phosphine","ids": [179],"t": "PH3 + HI → PH4I: PH3 acts as a Lewis base (lone pair on P).","exc": false,"tab": false,"src": "p15","page": 13,"o": "PH3 reacts with acids like HI to form PH4I which shows that it is basic in nature. Due to lone pair on phosphorus atom, PH3 is acting as a Lewis base in the above reaction."},{"sec": "Phosphorus trichloride","ids": [175],"t": "P halides: PX3 (X = F, Cl, Br, I) and PX5 (X = F, Cl, Br).","exc": false,"tab": false,"src": "p15","page": 13,"o": "Phosphorus forms two types of halides, PX3 (X = F, Cl, Br, I) and PX5 (X = F, Cl, Br)."},{"sec": "Phosphorus trichloride","ids": [176],"t": "PCl3: dry Cl2 over heated white P. P4 + 6Cl2 → 4PCl3","exc": false,"tab": false,"src": "p15","page": 13,"o": "It is obtained by passing dry chlorine over heated white phosphorus. P4 + 6Cl2 → 4PCl3"},{"sec": "Phosphorus trichloride","ids": [176],"t": "P4 + 8SOCl2 → 4PCl3 + 4SO2 + 2S2Cl2","exc": false,"tab": false,"src": "p15","page": 13,"o": "It is also obtained by the action of thionyl chloride with white phosphorus. P4 + 8SOCl2 → 4PCl3 + 4SO2 + 2S2Cl2"},{"sec": "Phosphorus trichloride","ids": [176],"t": "PCl3: colourless oily liquid; PCl3 + 3H2O → H3PO3 + 3HCl","exc": false,"tab": false,"src": "p15","page": 13,"o": "It is a colourless oily liquid and hydrolyses in the presence of moisture. PCl3 + 3H2O → H3PO3 + 3HCl"},{"sec": "Phosphorus trichloride","ids": [176],"t": "With –OH compounds: 3CH3COOH + PCl3 → 3CH3COCl + H3PO3; 3C2H5OH + PCl3 → 3C2H5Cl + H3PO3","exc": false,"tab": false,"src": "p15","page": 13,"o": "It reacts with organic compounds containing –OH group such as CH3COOH, C2H5OH. 3CH3COOH + PCl3 → 3CH3COCl + H3PO3; 3C2H5OH + PCl3 → 3C2H5Cl + H3PO3"},{"sec": "Phosphorus trichloride","ids": [176],"t": "PCl3: pyramidal, P sp^3.","exc": false,"tab": false,"src": "p15","page": 13,"o": "It has a pyramidal shape, in which phosphorus is sp^3 hybridised."},{"sec": "Phosphorus trichloride","ids": [187],"t": "PCl3 fumes in moist air (HCl).","exc": false,"tab": false,"src": "p15","page": 14,"o": "PCl3 hydrolyses in the presence of moisture giving fumes of HCl."},{"sec": "Phosphorus pentachloride","ids": [181],"t": "PCl5: white P + excess dry Cl2. P4 + 10Cl2 → 4PCl5","exc": false,"tab": false,"src": "p15","page": 14,"o": "Phosphorus pentachloride is prepared by the reaction of white phosphorus with excess of dry chlorine. P4 + 10Cl2 → 4PCl5"},{"sec": "Phosphorus pentachloride","ids": [181],"t": "P4 + 10SO2Cl2 → 4PCl5 + 10SO2","exc": false,"tab": false,"src": "p15","page": 14,"o": "It can also be prepared by the action of SO2Cl2 on phosphorus. P4 + 10SO2Cl2 → 4PCl5 + 10SO2"},{"sec": "Phosphorus pentachloride","ids": [181],"t": "PCl5: yellowish-white powder; hydrolyses in moist air: PCl5 + H2O → POCl3 + 2HCl; POCl3 + 3H2O → H3PO4 + 3HCl","exc": false,"tab": false,"src": "p15","page": 14,"o": "PCl5 is a yellowish white powder and in moist air, it hydrolyses to POCl3 and finally gets converted to phosphoric acid. PCl5 + H2O → POCl3 + 2HCl; POCl3 + 3H2O → H3PO4 + 3HCl"},{"sec": "Phosphorus pentachloride","ids": [181,182],"t": "Sublimes on heating, decomposes on stronger heating: PCl5 → PCl3 + Cl2","exc": false,"tab": false,"src": "p15","page": 14,"o": "When heated, it sublimes but decomposes on stronger heating. PCl5 → PCl3 + Cl2 (heat)"},{"sec": "Phosphorus pentachloride","ids": [182],"t": "With –OH compounds: C2H5OH + PCl5 → C2H5Cl + POCl3 + HCl; CH3COOH + PCl5 → CH3COCl + POCl3 + HCl","exc": false,"tab": false,"src": "p15","page": 14,"o": "It reacts with organic compounds containing –OH group converting them to chloro derivatives. C2H5OH + PCl5 → C2H5Cl + POCl3 + HCl; CH3COOH + PCl5 → CH3COCl + POCl3 + HCl"},{"sec": "Phosphorus pentachloride","ids": [182],"t": "With finely divided metals: 2Ag + PCl5 → 2AgCl + PCl3; Sn + 2PCl5 → SnCl4 + 2PCl3","exc": false,"tab": false,"src": "p15","page": 14,"o": "Finely divided metals on heating with PCl5 give corresponding chlorides. 2Ag + PCl5 → 2AgCl + PCl3; Sn + 2PCl5 → SnCl4 + 2PCl3"},{"sec": "Phosphorus pentachloride","ids": [182],"t": "Used to make C2H5Cl, CH3COCl.","exc": false,"tab": false,"src": "p15","page": 14,"o": "It is used in the synthesis of some organic compounds, e.g., C2H5Cl, CH3COCl."},{"sec": "Phosphorus pentachloride","ids": [183],"t": "PCl5 is trigonal bipyramidal in gas and liquid.","exc": false,"tab": false,"src": "p15","page": 14,"o": "In gaseous and liquid phases, it has a trigonal bipyramidal structure."},{"sec": "Phosphorus pentachloride","ids": [184,185],"t": "**3 equatorial P–Cl equal; 2 axial longer** (axial bond pairs suffer more repulsion).","exc": true,"tab": false,"src": "p15","page": 14,"o": "The three equatorial P–Cl bonds are equivalent, while the two axial bonds are longer than equatorial bonds. This is due to the fact that the axial bond pairs suffer more repulsion as compared to equatorial bond pairs."},{"sec": "Oxoacids of phosphorus","ids": [194],"t": "P oxoacids are interrelated by loss or gain of H2O or O.","exc": false,"tab": false,"src": "p15","page": 15,"o": "The compositions of the oxoacids are interrelated in terms of loss or gain of H2O molecule or O-atom."},{"sec": "Oxoacids of phosphorus","ids": [196,197],"t": "P is tetrahedral in all; each has at least one P=O and one P–OH.","exc": false,"tab": false,"src": "p15","page": 15,"o": "In oxoacids phosphorus is tetrahedrally surrounded by other atoms. All these acids contain at least one P=O bond and one P–OH bond."},{"sec": "Oxoacids of phosphorus","ids": [198],"t": "P below +5: also P–P (H4P2O6) or P–H (H3PO2) bonds, never both.","exc": false,"tab": false,"src": "p15","page": 15,"o": "The oxoacids in which phosphorus has lower oxidation state (less than +5) contain, in addition to P=O and P–OH bonds, either P–P (e.g., in H4P2O6) or P–H (e.g., in H3PO2) bonds but not both."},{"sec": "Oxoacids of phosphorus","ids": [199],"t": "+3 acids disproportionate.","exc": false,"tab": false,"src": "p15","page": 15,"o": "These acids in +3 oxidation state of phosphorus tend to disproportionate to higher and lower oxidation states."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "4H3PO3 → 3H3PO4 + PH3 (heat)","exc": false,"tab": false,"src": "p15","page": 15,"o": "For example, orthophophorous acid (or phosphorous acid) on heating disproportionates to give orthophosphoric acid (or phosphoric acid) and phosphine. 4H3PO3 → 3H3PO4 + PH3"},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Hypophosphorous (Phosphinic) H3PO2, +1; One P–OH, Two P–H, One P=O; from white P4 + alkali.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Hypophosphorous (Phosphinic) H3PO2, +1; One P–OH, Two P–H, One P=O; from white P4 + alkali."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Orthophosphorous (Phosphonic) H3PO3, +3; Two P–OH, One P–H, One P=O; from P2O3 + H2O.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Orthophosphorous (Phosphonic) H3PO3, +3; Two P–OH, One P–H, One P=O; from P2O3 + H2O."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Pyrophosphorous H4P2O5, +3; Two P–OH, Two P–H, Two P=O; from PCl3 + H3PO3.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Pyrophosphorous H4P2O5, +3; Two P–OH, Two P–H, Two P=O; from PCl3 + H3PO3."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Hypophosphoric H4P2O6, +4; Four P–OH, Two P=O, One P–P; from red P4 + alkali.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Hypophosphoric H4P2O6, +4; Four P–OH, Two P=O, One P–P; from red P4 + alkali."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Orthophosphoric H3PO4, +5; Three P–OH, One P=O; from P4O10 + H2O.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Orthophosphoric H3PO4, +5; Three P–OH, One P=O; from P4O10 + H2O."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Pyrophosphoric H4P2O7, +5; Four P–OH, Two P=O, One P–O–P; from heat phosphoric acid.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Pyrophosphoric H4P2O7, +5; Four P–OH, Two P=O, One P–O–P; from heat phosphoric acid."},{"sec": "Oxoacids of phosphorus","ids": [200],"t": "Table 7.5: Metaphosphoric (HPO3)n, +5 (exists in polymeric forms only); Three P–OH, Three P=O, Three P–O–P; from phosphorus acid + Br2, heat in a sealed tube.","exc": false,"tab": true,"src": "p15","page": 15,"o": "Table 7.5: Metaphosphoric (HPO3)n, +5 (exists in polymeric forms only); Three P–OH, Three P=O, Three P–O–P; from phosphorus acid + Br2, heat in a sealed tube."},{"sec": "Oxoacids of phosphorus","ids": [201],"t": "P–H bonds give strong reducing properties.","exc": false,"tab": false,"src": "p15","page": 16,"o": "The acids which contain P–H bond have strong reducing properties."},{"sec": "Oxoacids of phosphorus","ids": [202],"t": "H3PO2 (two P–H) reduces AgNO3 to Ag: 4AgNO3 + 2H2O + H3PO2 → 4Ag + 4HNO3 + H3PO4","exc": false,"tab": false,"src": "p15","page": 16,"o": "Thus, hypophosphorous acid is a good reducing agent as it contains two P–H bonds and reduces, for example, AgNO3 to metallic silver. 4AgNO3 + 2H2O + H3PO2 → 4Ag + 4HNO3 + H3PO4"},{"sec": "Oxoacids of phosphorus","ids": [202,203],"t": "**P–H hydrogens are not ionisable**; only P–OH hydrogens give basicity.","exc": true,"tab": false,"src": "p15","page": 16,"o": "These P–H bonds are not ionisable to give H^+ and do not play any role in basicity. Only those H atoms which are attached with oxygen in P–OH form are ionisable and cause the basicity."},{"sec": "Oxoacids of phosphorus","ids": [204],"t": "**H3PO3 is dibasic, H3PO4 tribasic** (2 and 3 P–OH).","exc": false,"tab": false,"src": "p15","page": 16,"o": "Thus, H3PO3 and H3PO4 are dibasic and tribasic, respectively as the structure of H3PO3 has two P–OH bonds and H3PO4 three."},{"sec": "Oxoacids of phosphorus","ids": [659,660],"t": "Basicity = number of P–OH groups; oxoacids with P–H bonds are good reductants.","exc": false,"tab": false,"src": "p15","page": 43,"o": "Depending upon the number of P–OH groups, their basicity varies. The oxoacids which have P–H bonds are good reducing agents."}]);
})();
